          commit(value);
        }
        return value;
      }, reason => {
        if (pending.get(key) === promise) pending.delete(key);
        throw reason;
      });
      pending.set(key, promise);
      return promise;
    },
    forget(key) {
      pending.delete(key);
    },
    clear() {
      pending.clear();
    }
  };
}

